package com.familyguard.parent;
import android.app.Activity; import android.os.Bundle; import android.graphics.Typeface; import android.widget.*;
public class MainActivity extends Activity { private TextView status; public void onCreate(Bundle b){ super.onCreate(b); LinearLayout root=new LinearLayout(this); root.setOrientation(1); root.setPadding(32,48,32,32); root.setBackgroundColor(0xFFF5F7FB); TextView title=new TextView(this); title.setText("FamilyGuard Parent"); title.setTextSize(28); title.setTypeface(null,Typeface.BOLD); title.setTextColor(0xFF18243A); TextView sub=new TextView(this); sub.setText("Family safety dashboard"); EditText code=new EditText(this); code.setHint("Enter Child pairing code"); code.setSingleLine(true); Button pair=new Button(this); pair.setText("Pair Child Device"); status=new TextView(this); status.setText("No child device paired. Secure server connection is not configured."); root.addView(title); root.addView(sub); root.addView(code); root.addView(pair); root.addView(status); pair.setOnClickListener(v->status.setText(code.getText().toString().trim().isEmpty()?"Enter a pairing code.":"Backend not configured. No device has been paired.")); setContentView(root); } }
